ALTER TABLE "product_spinner_button" ADD CONSTRAINT "product_spinner_button_measurements_positive" CHECK ("product_spinner_button"."weight_g" > 0 and "product_spinner_button"."diameter_mm" > 0 and "product_spinner_button"."thickness_mm" > 0);